#include "gap.h"
#include "token.h"
#include <dirent.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>

static int under_unitpit(const char *path) {
    static const char root[] = "/app/unitpit/";
    return path && strncmp(path, root, sizeof(root) - 1) == 0;
}

static int check_dumps(void) {
    DIR *d = opendir("/app/lotbay");
    struct dirent *ent;
    int bad = 0;
    if (!d) return 1;
    while ((ent = readdir(d)) != NULL) {
        char dump[PATH_MAX_X], name[NAME_MAX], orig[PATH_MAX_X];
        struct stat st;
        int line;
        if (ent->d_name[0] == '.') continue;
        snprintf(dump, sizeof dump, "/app/lotbay/%s", ent->d_name);
        if (stat(dump, &st) != 0 || !S_ISREG(st.st_mode)) continue;
        if (parse_lot(dump, name, orig, &line) != 0 ||
            !under_unitpit(orig) || !file_here(orig) || line < 1)
            bad = 1;
    }
    closedir(d);
    return bad;
}

static int check_atlas(void) {
    FILE *f = fopen("/app/inkwell/span.atlas", "r");
    char line[512], extra;
    int bad = 0;
    if (!f) return 1;
    if (!fgets(line, sizeof line, f) ||
        (strcmp(line, "SPAN1\n") != 0 && strcmp(line, "SPAN1\r\n") != 0 && strcmp(line, "SPAN1") != 0)) {
        fclose(f);
        return 1;
    }
    while (fgets(line, sizeof line, f)) {
        char name[NAME_MAX], path[PATH_MAX_X];
        int lo, hi;
        if (sscanf(line, "%63s %255s %d %d %c", name, path, &lo, &hi, &extra) != 4 ||
            !under_unitpit(path) || !file_here(path) || lo < 1 || hi < lo)
            bad = 1;
    }
    fclose(f);
    return bad;
}

int n_miss(void) {
    return check_dumps() || check_atlas();
}
